const r = await api.get("/mails", { label: "complaint" });
const list = r.items;
const out = [];
for (const m of list) {
  const c = await api.get(`/customers/${m.customer_id}`);
  out.push({ mail_id: m.id, customer_id: m.customer_id, tier: c.tier ?? null, keys: Object.keys(c) });
}
console.log(JSON.stringify(out.map(o => ({ mail_id: o.mail_id, customer_id: o.customer_id, tier: o.tier }))));
console.log("customer keys:", out.length ? out[0].keys : []);

